INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ich meinen Code immer kompilieren muss, um ihn auszuführen?', 2, '[{"text": "Nein", "correct": true, "because": "Interpretierte Sprachen brauchen das nicht"}, {"text": "Ja", "correct": false, "because": "Z. B. Python wird interpretiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft mir, die Lesbarkeit meines Programms zu verbessern?', 3, '[{"text": "Code-Formatter", "correct": true, "because": "Einheitliches Layout fördert Klarheit"}, {"text": "Debugger", "correct": false, "because": "Findet Fehler, nicht Stil"}, {"text": "Compiler", "correct": false, "because": "Übersetzt, formatiert nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken sichern die Wartbarkeit meines Programms?', 5, '[{"text": "Modulare Struktur", "correct": true, "because": "Ermöglicht isolierte Änderungen"}, {"text": "Dokumentation", "correct": true, "because": "Erklärt Logik und Zweck"}, {"text": "Maximale Optimierung", "correct": false, "because": "Kann Lesbarkeit schaden"}, {"text": "Viele globale Variablen", "correct": false, "because": "Erschwert Nachvollziehbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kommentare im Programm sind immer notwendig. b) Sie ersetzen eine externe Dokumentation.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Kommentare ergänzen, ersetzen nicht"}, {"text": "Beides stimmt", "correct": false, "because": "Kommentare nicht immer nötig"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Programm für Teamarbeit schreibe?', 4, '[{"text": "Konsistente Namenskonventionen", "correct": false, "because": "Wichtig für Klarheit"}, {"text": "Versionskontrolle", "correct": false, "because": "Schlüssel für Zusammenarbeit"}, {"text": "Persönliche Formatvorlieben", "correct": true, "because": "Teamstandards zählen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Programm ohne Tests immer unsicher ist. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Tests decken Fehler auf"}, {"text": "Nein", "correct": false, "because": "Tests sind Standard für Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ich meinen Code immer für maximale Performance optimieren?', 2, '[{"text": "Nein", "correct": true, "because": "Lesbarkeit oft wichtiger"}, {"text": "Ja", "correct": false, "because": "Kontext entscheidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Linter in der Entwicklung?', 3, '[{"text": "Findet Stilfehler", "correct": true, "because": "Erzwingt Code-Standards"}, {"text": "Optimiert Laufzeit", "correct": false, "because": "Nur Stil, nicht Performance"}, {"text": "Ersetzt Tests", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Programm ohne Refactoring langfristig wartbar bleibt?', 4, '[{"text": "Nein", "correct": true, "because": "Technische Schulden wachsen"}, {"text": "Ja", "correct": false, "because": "Ohne Anpassung wird’s unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Programm sicherer?', 5, '[{"text": "Input-Validierung", "correct": true, "because": "Verhindert Angriffe"}, {"text": "Fehlerbehandlung", "correct": true, "because": "Vermeidet Abstürze"}, {"text": "Hohe Zeilenanzahl", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Unabhängig von Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Programm für ein großes Team schreibe?', 4, '[{"text": "Klarheit und Struktur", "correct": true, "because": "Erleichtert Zusammenarbeit"}, {"text": "Minimale Dateigröße", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Programm sollte modular sein. b) Modularität erhöht immer die Laufzeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Modularität hilft, Laufzeit neutral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um meinen Code zu verbessern?', 3, '[{"text": "Unit-Tests", "correct": false, "because": "Sichern Funktionalität"}, {"text": "Code-Reviews", "correct": false, "because": "Fördern Qualität"}, {"text": "Exotische Syntax", "correct": true, "because": "Verwirrt mehr als hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich bei einem Programm mit vielen Entwicklern vorgehe?', 4, '[{"text": "Versionskontrolle einrichten", "correct": true, "because": "Koordiniert Änderungen"}, {"text": "Lokale Kopien verteilen", "correct": false, "because": "Führt zu Chaos"}, {"text": "Manuelle Merges", "correct": false, "because": "Fehleranfällig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Programm ohne Dokumentation nutzlos ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Guter Code ist selbsterklärend"}, {"text": "Ja", "correct": false, "because": "Dokumentation ergänzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft mir, meinen Code sauber zu halten?', 3, '[{"text": "DRY-Prinzip", "correct": true, "because": "Vermeidet Redundanzen"}, {"text": "Maximale Funktionen", "correct": false, "because": "Keine Regel"}, {"text": "Hohe Zeilenanzahl", "correct": false, "because": "Kein Qualitätsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Programm mit vielen Kommentaren immer besser?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität zählt, nicht Quantität"}, {"text": "Ja", "correct": false, "because": "Überflüssige Kommentare stören"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen ein Programm wartungsfreundlich?', 5, '[{"text": "Konsistente Struktur", "correct": true, "because": "Erleichtert Verständnis"}, {"text": "Klar benannte Variablen", "correct": true, "because": "Fördert Lesbarkeit"}, {"text": "Maximale Kompression", "correct": false, "because": "Schadet Klarheit"}, {"text": "Viele Abhängigkeiten", "correct": false, "because": "Kompliziert Änderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Programm für Kunden unwichtig?', 3, '[{"text": "Fehlerfreie Funktion", "correct": false, "because": "Kern der Qualität"}, {"text": "Benutzerfreundlichkeit", "correct": false, "because": "Schlüssel für Akzeptanz"}, {"text": "Interne Variablennamen", "correct": true, "because": "Kunde sieht sie nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich ein Programm für Langzeitnutzung schreibe?', 4, '[{"text": "Modularität fördern", "correct": true, "because": "Erleichtert Updates"}, {"text": "Alles in eine Datei", "correct": false, "because": "Schwer wartbar"}, {"text": "Keine Tests", "correct": false, "because": "Risiko für Fehler"}]');
